```python
def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if not lib.is_scalar(value):
        value = np.asarray(value)

    values = self._ndarray

    # Determine if we need to change the dtype
    if isinstance(value, str):
        # If value is a string, check if it can be represented by the current dtype
        if values.dtype.kind == 'O':
            # If current dtype is object, we can assign the string directly
            values[key] = value
        elif values.dtype.kind == 'U':
            # If current dtype is unicode, we can assign the string directly
            values[key] = value
        else:
            # If current dtype is not object or unicode, try to find a common dtype
            try:
                t = np.promote_types(values.dtype, np.dtype('U'))
                values = values.astype(t)
                values[key] = value
                self._dtype = PandasDtype(t)
                self._ndarray = values
            except TypeError:
                # If promotion fails, raise an error
                raise ValueError(f"Cannot assign string '{value}' to array with dtype {values.dtype}")
    else:
        # If value is not a string, find a common dtype
        t = np.result_type(value, values)
        if t!= self._ndarray.dtype:
            values = values.astype(t, casting="safe")
            values[key] = value
            self._dtype = PandasDtype(t)
            self._ndarray = values
        else:
            self._ndarray[key] = value
```

