def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if not lib.is_scalar(value):
        value = np.asarray(value)

    # Check if the dtype of the value is compatible with the dtype of the array
    if self._ndarray.dtype.kind == 'O' and not isinstance(value, str):
        values = np.array([value], dtype=object)
    else:
        values = np.array([value], dtype=self._ndarray.dtype)

    t = np.find_common_type([values.dtype, self._ndarray.dtype], [])

    if t!= self._ndarray.dtype:
        self._ndarray = self._ndarray.astype(t, casting="safe")
        self._dtype = PandasDtype(t)

    self._ndarray[key] = value
```

